<docs>
Use this screen at the end of your experiment to submit the data to the server.
You can provide the submission URL to the Experiment component.
</docs>

<template>
  <Screen v-if="!$magpie.debug" title="Submitting">
    <Slide>
      <p>{{ $t('screens.SubmitResultsScreen.waiting') }}</p>
      <Wait :time="0" @done="submit()" />
    </Slide>

    <Slide>
      <div v-if="!error">
        <p>
          Your responses have been submitted successfully.
        </p>

        <p>
          Your completion code is:
        </p>

        <p>
          <strong>{{ completionCode }}</strong>
        </p>

        <p>
          To receive your compensation, please email
          <a :href="emailLink">
            {{ researcherEmail }}
          </a>
          and include this completion code in your message.
        </p>

        <p>
          You will then receive a participation certificate by email.
          Please complete and sign the certificate and return it by email.
          Once the signed certificate has been received, your gift card
          will be sent to you.
        </p>
      </div>

      <div v-else>
        <p>{{ $t('screens.SubmitResultsScreen.error') }}</p>

        <p>
          {{ $t('screens.SubmitResultsScreen.contact') }}
          <a :href="'mailto:' + $magpie.contactEmail">
            {{ $magpie.contactEmail }}
          </a>.
        </p>

        <p v-text="error" />
      </div>
    </Slide>
  </Screen>

  <DebugResultsScreen v-else />
</template>

<script>
import Screen from '../Screen';
import Wait from '../helpers/Wait';
import DebugResultsScreen from './DebugResultsScreen';
import Slide from '../Slide';

export default {
  name: 'SubmitResultsScreen',

  components: {
    Screen,
    Slide,
    Wait,
    DebugResultsScreen
  },

  data() {
    return {
      error: null,
      completionCode: '',
      researcherEmail: 'gemma.seghi@uni-tuebingen.de'
    };
  },

  computed: {
    emailLink() {
      const subject = encodeURIComponent(
        'Study completion and compensation'
      );

      const body = encodeURIComponent(
        `Hello,\n\n` +
          `I have completed the experiment.\n\n` +
          `My completion code is: ${this.completionCode}\n\n` +
          `Please send me the participation certificate.\n`
      );

      return (
        `mailto:${this.researcherEmail}` +
        `?subject=${subject}` +
        `&body=${body}`
      );
    }
  },

  created() {
    this.completionCode = this.getOrCreateCompletionCode();

    this.$magpie.addExpData({
      recruitment_source: 'paid',
      payment_completion_code: this.completionCode
    });
  },

  methods: {
    getOrCreateCompletionCode() {
      const storageKey = 'study-72-paid-completion-code';

      // Reuse the code if this component is recreated in the same tab.
      const existingCode =
        window.sessionStorage.getItem(storageKey);

      if (existingCode) {
        return existingCode;
      }

      let randomPart;

      if (
        window.crypto &&
        typeof window.crypto.getRandomValues === 'function'
      ) {
        const randomBytes = new Uint8Array(8);
        window.crypto.getRandomValues(randomBytes);

        randomPart = Array.from(randomBytes)
          .map((byte) =>
            byte.toString(16).padStart(2, '0')
          )
          .join('')
          .toUpperCase();
      } else {
        // Fallback for browsers without Web Crypto support.
        randomPart = (
          Date.now().toString(36) +
          Math.random().toString(36).slice(2)
        )
          .slice(0, 16)
          .toUpperCase();
      }

      const code = `PAID-${randomPart}`;

      window.sessionStorage.setItem(storageKey, code);

      return code;
    },

    async submit() {
      try {
        // The completion code has already been added to the
        // experiment-level data.
        await this.$magpie.submit();

        // The data were saved, so the participant may now leave.
        this.disableUnloadWarning();

        // Show the completion code and payment instructions.
        this.$magpie.nextSlide();
      } catch (err) {
        this.error =
          err instanceof Error
            ? err.message
            : String(err);

        // Display the submission error without showing payment details.
        this.$magpie.nextSlide();
      }
    },

    disableUnloadWarning() {
      const experiment = this.$magpie.experiment;

      if (
        experiment &&
        typeof experiment.disableBeforeUnload === 'function'
      ) {
        experiment.disableBeforeUnload();
      }
    }
  }
};
</script>
